GRANT INSERT(user_id,kind,amount,method,account_number,transaction_id,proof_path) ON public.payment_requests TO authenticated;
CREATE POLICY submit_own_request ON public.payment_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND reserved=false AND reviewed_by IS NULL AND reviewed_at IS NULL AND payout_reference IS NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active') AND (kind='withdrawal' OR proof_path LIKE auth.uid()::text||'/%'));
CREATE UNIQUE INDEX unique_deposit_reference ON public.payment_requests(method,transaction_id) WHERE kind='deposit';
CREATE FUNCTION public.validate_payment_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE available numeric; pending numeric; BEGIN SELECT balance INTO available FROM public.profiles WHERE id=new.user_id AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Account unavailable'; END IF; IF new.kind='withdrawal' THEN IF new.account_number !~ '^01[3-9][0-9]{8}$' THEN RAISE EXCEPTION 'Enter a valid Bangladesh mobile number'; END IF; SELECT coalesce(sum(amount),0) INTO pending FROM public.payment_requests WHERE user_id=new.user_id AND kind='withdrawal' AND status='pending'; IF new.amount>available-pending THEN RAISE EXCEPTION 'Insufficient available wallet balance'; END IF; END IF; RETURN new; END; $$;
CREATE TRIGGER validate_payment_request BEFORE INSERT ON public.payment_requests FOR EACH ROW EXECUTE FUNCTION public.validate_payment_request();